document.head.insertAdjacentHTML('beforeend','<style>.live-picker-orb{position:fixed;right:28px;bottom:28px;z-index:2147483000;touch-action:none;user-select:none}.live-picker-orb>button{width:64px;height:64px;border:1px solid rgba(255,255,255,.55);border-radius:50%;background:radial-gradient(circle at 35% 25%,#fff,#cfcfcf 35%,#777 72%,#222);color:#111;font:800 13px -apple-system,BlinkMacSystemFont,sans-serif;box-shadow:0 0 0 6px rgba(255,255,255,.08),0 0 30px rgba(255,255,255,.4),0 14px 32px rgba(0,0,0,.55);cursor:grab;transition:.2s}.live-picker-orb.dragging>button{cursor:grabbing;transform:scale(1.06)}.live-picker-orb>button:hover{transform:scale(1.08)}.live-picker-orb>button span{display:block;font-size:10px;margin-top:2px}.live-picker-orb.attention>button{animation:live-picker-pulse 1s ease-in-out infinite}.live-picker-popover{position:absolute;right:0;bottom:78px;width:min(300px,calc(100vw - 32px));max-height:min(420px,calc(100vh - 120px));overflow:auto;padding:16px;border:1px solid #444;border-radius:14px;background:#191919;box-shadow:0 18px 50px rgba(0,0,0,.65);overscroll-behavior:contain}.live-picker-popover h3{margin:0;font-size:16px}.live-picker-popover p{margin:8px 0 12px;color:#aaa;font-size:12px;line-height:1.5}.live-picker-models{display:grid;gap:7px;max-height:280px;overflow:auto;padding-right:3px;overscroll-behavior:contain}.live-picker-models button{padding:10px 12px;border:1px solid #3b3b3b;border-radius:9px;background:#242424;color:#fff;text-align:left;cursor:pointer}.live-picker-models button:hover{border-color:#fff;background:#303030}.live-picker-footer{display:flex;justify-content:flex-end;margin-top:12px}.live-picker-footer button{border:0;background:none;color:#999;cursor:pointer}@keyframes live-picker-pulse{50%{box-shadow:0 0 0 13px rgba(255,255,255,.03),0 0 42px rgba(255,255,255,.8),0 14px 32px rgba(0,0,0,.55)}}@media(max-width:760px){.live-picker-orb{right:18px;bottom:18px}}</style>');
function toast(message,error){const el=q('#toast');el.textContent=message;el.className='toast show'+(error?' error':'');setTimeout(function(){el.className='toast'},3400)}
async function runButton(button,labels,task){if(button&&button.dataset.busy==='1')return;if(!button)return task();const original=button.textContent;button.disabled=true;button.dataset.busy='1';button.classList.remove('pending','success','error');button.classList.add('pending');button.textContent=labels.loading;try{const result=await task();button.classList.remove('pending');button.classList.add('success');button.textContent=labels.success;setTimeout(function(){button.classList.remove('success');button.dataset.busy='';button.disabled=false;button.textContent=original},1200);return result}catch(error){button.classList.remove('pending');button.classList.add('error');button.textContent=labels.failure;setTimeout(function(){button.classList.remove('error');button.dataset.busy='';button.disabled=false;button.textContent=original},1800);throw error}}
function post(url,data){return api(url,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data||{})})}
function openView(view){document.querySelectorAll('.view').forEach(function(el){el.classList.remove('active')});document.querySelectorAll('[data-view]').forEach(function(el){el.classList.toggle('active',el.dataset.view===view)});q('#view-'+view).classList.add('active');try{sessionStorage.setItem('opencodex.dashboard.view',view)}catch(e){}if(view==='voice')loadVoice();if(view==='sessions')loadSessions();if(view==='logs')loadLogs();if(view==='settings')loadCapabilityTokens()}
document.querySelectorAll('[data-view]').forEach(function(el){el.onclick=function(){openView(el.dataset.view)}});
function presetSymbol(p){return ({deepseek:'D',qwen:'Q',zai:'Z',minimax:'M',kimi:'K',openrouter:'◈','opencode-go':'⚙',siliconflow:'⚡',volcengine:'▲',custom:'+'})[p.id]||String(p.label||'?').slice(0,1)}
function providerIcon(p){
  const klass='brand-icon brand-'+esc(p.id);
  if(p.id==='volcengine') return '<span class="'+klass+'" style="background:#111622"><svg viewBox="0 0 24 24" width="22" height="22"><path fill="#ff4d4f" d="M12 3L2 19h5.5l4.5-7.5L16.5 19H22L12 3z"/><path fill="#ffa940" d="M12 8.5l-3 5h6l-3-5z"/></svg></span>';
  if(p.id==='siliconflow') return '<span class="'+klass+'" style="background:#091220"><svg viewBox="0 0 24 24" width="22" height="22"><path fill="#0091ff" d="M12 2L3.5 7v10L12 22l8.5-5V7L12 2zm6.5 14.1L12 19.4l-6.5-3.3V7.9L12 4.6l6.5 3.3v8.2z"/><path fill="#0091ff" d="M12 7.5L7.5 10v4l4.5 2.5 4.5-2.5v-4L12 7.5z"/></svg></span>';
  if(p.id==='opencode-go') return '<span class="'+klass+'" style="background:#172234"><svg viewBox="0 0 24 24" width="20" height="20"><path fill="#38bdf8" d="M9.4 16.6L4.8 12l4.6-4.6L8 6l-6 6 6 6 1.4-1.4zm5.2 0l4.6-4.6-4.6-4.6L16 6l6 6-6 6-1.4-1.4z"/></svg></span>';
  if(p.id==='custom') return '<span class="'+klass+'"><svg viewBox="0 0 24 24" width="20" height="20"><path fill="#FFFFFF" d="M19 13h-6v6h-2v-6H5v-2h6V5h2v6h6v2z"/></svg></span>';
  const icon=p.iconUrl|| (p.iconSlug?'https://cdn.simpleicons.org/'+esc(p.iconSlug):'');
  return icon?'<span class="'+klass+'"><img src="'+esc(icon)+'" alt=""></span>':'<span class="'+klass+'">'+esc(presetSymbol(p))+'</span>';
}
function subscriptionIcon(key){
  const klass='brand-icon brand-'+esc(key);
  if(key==='antigravity')return '<span class="'+klass+'"><img src="https://antigravity.google/assets/image/brand/antigravity-icon__full-color.png" alt=""></span>';
  if(key==='claude')return '<span class="'+klass+'"><img src="https://cdn.simpleicons.org/anthropic/cc785c" alt=""></span>';
  if(key==='cursor')return '<span class="'+klass+'" style="background:transparent"><img src="data:image/png;base64," alt="Cursor"></span>';
  return '<span class="'+klass+'"><svg viewBox="0 0 24 24" role="img" aria-label="Grok"><circle cx="12" cy="12" r="8.1" fill="none" stroke="#101216" stroke-width="3.1"/><path d="M5.1 18.9 18.9 5.1" fill="none" stroke="#101216" stroke-width="3.1" stroke-linecap="square"/></svg></span>';
}
function providerForPreset(id){return state.providers.find(function(p){return p.preset_id===id})||state.providers.find(function(p){return p.id===id})}
function isConnected(p){return p&&['connected','simulated'].includes(p.status)}
function isSaved(p){return p&&p.status!=='not_configured'}
async function loadGateway(){try{const d=await api('/api/gateway/status');state.gatewayActive=Boolean(d.active);document.title=d.active?'OpenCodex · 网关已启用':'OpenCodex · 原生模式';renderApiProviders();renderEnabledModels()}catch(e){}}
async function loadPresets(){const d=await api('/api/providers/presets');state.presets=d.presets||[];renderApiProviders()}
async function loadProviders(){const d=await api('/api/providers');state.providers=d.providers||[];renderApiProviders();renderEnabledModels()}
function renderApiProviders(){const root=q('#api-provider-list');if(!root||!state.presets.length)return;const core=['deepseek','qwen','zai','minimax','kimi'];const extra=['openrouter','opencode-go','siliconflow','volcengine'];const ids=state.showMoreProviders?core.concat(extra).concat(['custom']):core.concat(['custom']);const cards=ids.map(function(id){const p=state.presets.find(function(item){return item.id===id});if(!p)return '';const current=providerForPreset(p.id);const saved=isSaved(current);const hasActiveModels=Boolean(current&&Array.isArray(current.active_models)&&current.active_models.some(function(model){return model.enabled!==false}));const active=state.gatewayActive&&hasActiveModels;const detail=p.id==='custom'?'填写兼容 URL、模型名与 API Key':active?'Key 已保存 · 在下方管理模型':saved?'Key 已保存 · 未启用':'预设地址与模型 · 仅填写 API Key';return '<div class="provider-row '+(p.id==='custom'?'custom':'')+'"><div class="provider-symbol">'+providerIcon(p)+'</div><div class="provider-copy"><b>'+esc(p.id==='custom'?'自定义 OpenAI Compatible':p.label)+'</b><span>'+esc(detail)+'</span></div><span class="status '+(active?'good':'')+'">'+(active?'已启用':saved?'已保存 · 未启用':'')+'</span><button class="button" data-configure="'+esc(p.id)+'">'+(current?'管理':'配置')+'</button></div>'}).join('');const more='<div class="provider-row"><div class="provider-symbol">+</div><div class="provider-copy"><b>'+ (state.showMoreProviders?'收起其他预设':'更多常用服务商') +'</b><span>OpenRouter · OpenCode Go · SiliconFlow · 火山方舟</span></div><button class="button" id="toggle-more-providers">'+(state.showMoreProviders?'收起':'查看')+'</button></div>';root.innerHTML=cards+more;document.querySelectorAll('[data-configure]').forEach(function(el){el.onclick=function(){openProviderModal(el.dataset.configure)}});q('#toggle-more-providers').onclick=function(){state.showMoreProviders=!state.showMoreProviders;renderApiProviders()}}
function openProviderModal(presetId){const preset=state.presets.find(function(p){return p.id===presetId});if(!preset)return;state.candidate=null;const current=providerForPreset(preset.id);const savedKey=Boolean(current&&current.credential_storage&&current.credential_storage!=='none');const old=q('#custom-fields');if(old)old.remove();const oldModels=q('#model-fields');if(oldModels)oldModels.remove();const custom=preset.id==='custom';const currentUrl=(current&&(current.baseUrl||current.base_url))||preset.defaultBaseUrl||'';q('#candidate-note').insertAdjacentHTML('beforebegin','<div id="custom-fields" class="form-grid"><label class="field wide">Endpoint / Base URL<input id="custom-url" placeholder="https://api.example.com/v1" value="'+esc(currentUrl)+'" required></label></div>');const suggested=(preset.models||[]).slice(0,2).map(function(model){return model.id}).join(', ')||'例如 model-name';const existingModels=(current&&Array.isArray(current.models)?current.models:[]).join(', ');q('#candidate-note').insertAdjacentHTML('beforebegin','<div id="model-fields" class="form-grid"><label class="field wide">模型名称 / 别名映射（用英文逗号分隔）<input id="provider-models" placeholder="'+esc(suggested)+'" value="'+esc(existingModels)+'" required></label><p class="help wide">同名模型需映射：显示名=实际模型名，例如 deepseek-chat-direct=deepseek-chat。还原原生后模型目录会清空，Key 会保留。</p></div>');q('#provider-modal').dataset.preset=preset.id;q('#provider-modal').dataset.savedKey=savedKey?'1':'';q('#provider-modal-title').textContent=custom?'配置自定义兼容接口':(savedKey?'管理 '+preset.label:'配置 '+preset.label);q('#provider-modal-copy').textContent=custom?'填写兼容 URL、API Key 与要添加的模型名称。保存后模型进入待应用清单，重启 Codex 后才生效.':savedKey?'API Key 已保存在 macOS Keychain。Key 输入框可以留空，直接填写模型名称后点击“保存并添加模型”；如需更换 Key，再输入新 Key。':'接口 Endpoint 已自动预设，可按需修改。填写 API Key 与要添加的模型名称；保存后自动写入待应用清单。';q('#provider-key').value='';q('#provider-key').required=!savedKey;q('#provider-key').placeholder=savedKey?'已保存于 macOS Keychain；留空以继续使用':'保存后写入 macOS Keychain';q('#candidate-note').className='note hidden';q('#confirm-enable').classList.add('hidden');q('#test-candidate').classList.remove('hidden');q('#test-candidate').textContent='保存并添加模型';q('#provider-modal').classList.add('show');q(savedKey?'#provider-models':'#provider-key').focus()}
function closeProviderModal(){q('#provider-modal').classList.remove('show');state.candidate=null}
q('#close-modal').onclick=closeProviderModal;
q('#provider-form').onsubmit=async function(event){event.preventDefault();const preset=state.presets.find(function(p){return p.id===q('#provider-modal').dataset.preset});const key=q('#provider-key').value.trim();const savedKey=q('#provider-modal').dataset.savedKey==='1';if(!preset||(!key&&!savedKey)){toast('请输入 API Key，或使用已保存的 Key',true);return}const endpoint=q('#custom-url').value.trim()||preset.defaultBaseUrl;const selected=q('#provider-models').value.split(',').map(function(id){return id.trim()}).filter(Boolean);if(!endpoint||!selected.length){toast('请填写 Endpoint 和至少一个模型名称',true);return}const candidate={preset_id:preset.id,name:preset.id,auth_mode:'api_key',base_url:endpoint,api_key:key,selected_models:selected,install_models:true};try{await runButton(q('#test-candidate'),{loading:'保存中…',success:'保存成功',failure:'保存失败'},async function(){await post('/api/providers',candidate);closeProviderModal();await Promise.all([loadGateway(),loadProviders(),loadModels()])});toast(key?'API Key 已更新，模型已加入待应用清单':'已复用已保存的 API Key，模型已加入待应用清单')}catch(e){toast(e.message,true)}};
async function testProvider(name,button){try{await runButton(button,{loading:'测试中…',success:'测试成功',failure:'测试失败'},async function(){const result=await post('/api/providers/test',{name:name});await Promise.all([loadProviders(),loadSubscriptions()]);renderEnabledModels();if(!['connected','simulated'].includes(result.status))throw new Error(result.message||'连接测试失败');return result});toast('连接测试已完成')}catch(e){toast(e.message,true)}}
async function deleteProvider(name,button){try{await runButton(button,{loading:'删除中…',success:'已删除',failure:'删除失败'},async function(){await post('/api/providers/delete',{name:name});await syncDashboardState()});toast('服务商已移除')}catch(e){toast(e.message,true)}}
async function deleteModel(id,button){try{await runButton(button,{loading:'删除中…',success:'已删除',failure:'删除失败'},async function(){await post('/api/models/delete',{id:id});await syncDashboardState()});toast('模型已从待应用清单删除')}catch(e){toast(e.message,true)}}
async function loadSubscriptions(){const root=q('#subscription-list');try{const data=await api('/api/cli-bridge/status');state.subscriptionsData=data;const items=[['antigravity','Antigravity'],['grok','Grok'],['claude','Claude'],['cursor','Cursor']];root.innerHTML=items.map(function(item){const key=item[0],label=item[1],info=data[key]||{},detected=Boolean(info.detected),active=Boolean(info.active),stateLabel=active?'已导入':detected?'已检测到':'未检测到';return '<div class="subscription-row"><div class="provider-symbol">'+subscriptionIcon(key)+'</div><div class="provider-copy"><b>'+esc(label)+'</b><span>'+esc(active?'已由你导入，可重新测试连接':detected?'本机登录态已发现，尚未导入':'未发现本机登录态')+'</span></div><span class="status '+(active?'good':detected?'warn':'')+'">'+stateLabel+'</span><button class="button '+(active?'hidden':'')+'" data-subscription="'+key+'" '+(!detected?'disabled':'')+'>'+ (detected?'导入':'等待登录') +'</button></div>'}).join('');document.querySelectorAll('[data-subscription]').forEach(function(el){el.onclick=function(){activateSubscription(el.dataset.subscription)}})}catch(e){root.innerHTML='<div class="empty">无法检测本机订阅：'+esc(e.message)+'</div>'}}

async function activateSubscription(name){const button=q('[data-subscription="'+esc(name)+'"]');try{await runButton(button,{loading:'导入中…',success:'导入成功',failure:'导入失败'},async function(){await post('/api/cli-bridge/activate',{cli:name});await syncDashboardState()});toast('订阅模型已导入')}catch(e){toast(e.message,true)}}
async function loadModels(){try{const d=await api('/api/models');state.models=d.catalog||[];renderEnabledModels()}catch(e){q('#enabled-models').innerHTML='<div class="empty">'+esc(e.message)+'</div>'}}
async function syncDashboardState(){await Promise.all([loadGateway(),loadProviders(),loadSubscriptions(),loadModels()]);renderApiProviders();renderEnabledModels()}
function findProviderForModel(model){const providerKey=model.backend_provider||model.provider;const found=state.providers.find(function(p){return p.id===providerKey||p.preset_id===providerKey})||state.providers.find(function(p){return (p.active_models||[]).some(function(m){return m.id===model.id})});if(found)return found;const subData=state.subscriptionsData&&state.subscriptionsData[providerKey];if(subData){return {id:providerKey,status:subData.active?'active':(subData.detected?'configured':'not_configured'),test_status:subData.test_status||'untested',test_message:subData.test_message||''}}return {id:providerKey,status:'configured',test_status:'untested'}}
function renderEnabledModels(){const root=q('#enabled-models');const restart=q('#restart-button');if(!root)return;const staged=state.models.filter(function(m){return true});if(restart){restart.disabled=!staged.length||!state.gatewayActive;restart.title=staged.length?(state.gatewayActive?'重启 Codex 后将待应用模型写入 Desktop 菜单':'当前为原生模式，已暂停第三方模型'):'添加至少一个第三方模型后才可重启'}if(!staged.length){root.innerHTML='<div class="empty">尚未添加第三方模型。先保存 API Key，或导入本机订阅。</div>';return}root.innerHTML=staged.map(function(model){const mid=model.slug||model.id;const provider=findProviderForModel(model);const providerId=provider&&provider.id;const providerStatus=provider&&provider.test_status||'untested';const connected=['connected','simulated'].includes(providerStatus);const failed=providerStatus==='failed';const statusLabel=connected?'已连接':failed?'连接失败':'待测试';const statusClass=connected?'good':failed?'error':'pending';return '<div class="model-row"><div class="model-name"><div class="model-icon">'+esc(String(model.display_name||mid).slice(0,1).toUpperCase())+'</div><div><b>'+esc(model.display_name||mid)+'</b><span>'+esc(mid)+'</span></div></div><span class="model-state '+statusClass+'">'+statusLabel+'</span><span><button class="button" data-test-model="'+esc(providerId||model.backend_provider||'')+'">'+(connected?'重新测试':'测试连接')+'</button> <button class="button" data-delete-model="'+esc(mid)+'">删除</button></span></div>'}).join('');document.querySelectorAll('[data-test-model]').forEach(function(el){el.onclick=function(){if(el.dataset.testModel)testProvider(el.dataset.testModel,el);else toast('该模型没有可测试的服务商',true)}});document.querySelectorAll('[data-delete-model]').forEach(function(el){el.onclick=function(){deleteModel(el.dataset.deleteModel,el)}})}

function syncVoiceFields(){const sttApi=q('#stt-engine').value==='openai-compatible'||q('#stt-engine').value==='groq';q('#stt-local-fields').classList.toggle('hidden',sttApi);q('#stt-api-fields').classList.toggle('hidden',!sttApi);const engine=q('#tts-engine').value;const ttsApi=['openai-compatible','doubao','minimax','mimo'].includes(engine);q('#tts-api-fields').classList.toggle('hidden',!ttsApi);q('#tts-doubao-fields').classList.toggle('hidden',engine!=='doubao');const ttsUrl=q('#tts-base-url'),ttsModel=q('#tts-model'),ttsKey=q('#tts-api-key'),voice=q('#tts-voice');if(engine==='doubao'){ttsUrl.placeholder='https://openspeech.bytedance.com/api/v3/tts/unidirectional';ttsModel.placeholder='seed-tts-2.0-expressive';ttsKey.placeholder='火山 API Key'}else if(engine==='minimax'){ttsUrl.placeholder='https://api.minimaxi.com';ttsModel.placeholder='speech-2.8-turbo';ttsKey.placeholder='MiniMax API Key';voice.placeholder='female-shaonv'}else if(engine==='mimo'){ttsUrl.placeholder='https://api.xiaomimimo.com';ttsModel.placeholder='mimo-v2.5-tts';ttsKey.placeholder='MiMo API Key';voice.placeholder='Chloe'}else{ttsUrl.placeholder='https://api.openai.com/v1';ttsModel.placeholder='tts-1';ttsKey.placeholder='API Key';voice.placeholder=engine==='edge-tts'?'zh-CN-XiaoxiaoNeural':'alloy'}}
function updateVoiceBarStatus(status){q('#voice-status').textContent=status.running?'语音栏运行中':status.available?'语音栏未运行':'未安装 OpenCodexBar';q('#voice-running').textContent=status.running?'运行中':status.available?'未运行':'未安装';q('#voice-running').className='status '+(status.running?'good':'');q('#restart-cdp').disabled=!status.available;q('#restart-cdp').title=status.message||''}
